// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // Fuzz the caller address (who will send the call) and an arbitrary non-empty calldata length
    function testFuzz_property(address caller, uint256 dataLen) public {
        // keep dataLen in a reasonable bound but allow zero too; we will pass at least one byte when needed
        uint256 len = bound(dataLen, 0, 256);

        // Deploy an adversarial callee that ALWAYS reverts on any call/fallback
        Reverter rev = new Reverter();

        // Prepare some calldata of length `len` (can be zero)
        bytes memory payload = new bytes(len);
        // fill with something so it's not all zeros for most fuzz cases
        for (uint256 i = 0; i < len; i++) {
            payload[i] = bytes1(uint8(i & 0xff));
        }

        // Make the call to c.forward come from `caller` (fuzzed actor). If caller needs funds, give some.
        vm.deal(caller, 1 ether);
        vm.prank(caller);

        // The reference C: when callee.reverts, the low-level call returns (bool=false) and require(_s) in reference causes revert.
        // We observe whether c.forward reverted by try/catch. The universal property:
        //   For ANY caller and ANY calldata, when the callee reverts, the correct contract's forward ALWAYS reverts.
        // The mutant negates the success flag and will not revert in that case; thus some inputs (here all inputs) distinguish them.

        bool ok;
        try c.forward(address(rev), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the universal property: for a callee that reverts, c.forward must revert (ok == false).
        // This holds for the reference implementation for ALL inputs; the mutant (which negates _s before require)
        // will instead allow the call to succeed (ok == true) and so will fail this assertion for some inputs.
        assertTrue(!ok);
    }
}

// Adversarial callee that ALWAYS reverts on any call/fallback
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
